export type ParsedDelegatePullInstruction<
  TProgram extends string = typeof TEQUILA_GACHA_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    player: TAccountMetas[0];
    machine: TAccountMetas[1];
    playerState: TAccountMetas[2];
    bufferPull: TAccountMetas[3];
    delegationRecordPull: TAccountMetas[4];
    delegationMetadataPull: TAccountMetas[5];
    pull: TAccountMetas[6];
    ownerProgram: TAccountMetas[7];
    delegationProgram: TAccountMetas[8];
    systemProgram: TAccountMetas[9];
  };
  data: DelegatePullInstructionData;
};

export function parseDelegatePullInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedDelegatePullInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 10) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 10,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      player: getNextAccount(),
      machine: getNextAccount(),
      playerState: getNextAccount(),
      bufferPull: getNextAccount(),
      delegationRecordPull: getNextAccount(),
      delegationMetadataPull: getNextAccount(),
      pull: getNextAccount(),
      ownerProgram: getNextAccount(),
      delegationProgram: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getDelegatePullInstructionDataDecoder().decode(instruction.data),
  };
}
